    int n;
    cin >> n;
    int sum = 0;
    // 用循环累加 1 到 n
    cout << sum;
    return 0;
}

questions.solution:
#include <iostream>
using namespace std;
int main(){int n;cin>>n;int s=0;for(int i=1;i<=n;i++)s+=i;cout<<s;return 0;}

