questions.solution:
#include <iostream>
using namespace std;
int main(){int n;cin>>n;long long a=1,b=1;if(n==1||n==2){cout<<1;return 0;}for(int i=3;i<=n;i++){long long t=a+b;a=b;b=t;}cout<<b;return 0;}
